sys_script_include.script:
var XalientGlideAjaxHelper = Class.create();
XalientGlideAjaxHelper.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	getToken: function () {
		const rm_token = new sn_ws.RESTMessageV2('SailPoint ISC', 'access-token-get');
		rm_token.setStringParameterNoEscape('tenant', gs.getProperty('x_xal_idconnect.isc_tenant'));
		rm_token.setStringParameterNoEscape('domain', gs.getProperty('x_xal_idconnect.domain'));
		rm_token.setStringParameterNoEscape('client_id', gs.getProperty('x_xal_idconnect.isc_client_id'));
		rm_token.setStringParameterNoEscape('client_secret', gs.getProperty('x_xal_idconnect.isc_client_secret'));

		const res_token = rm_token.execute();
		const resb_token = JSON.parse(res_token.getBody());

		return resb_token.access_token;
	},

	getIdentity: function () {
		const filter = this.getParameter('sysparm_filter');
		const access_token = this.getToken();

		const rm_identity = new sn_ws.RESTMessageV2('SailPoint ISC', 'identities-list');
		rm_identity.setStringParameterNoEscape('tenant', gs.getProperty('x_xal_idconnect.isc_tenant'));
		rm_identity.setStringParameterNoEscape('domain', gs.getProperty('x_xal_idconnect.domain'));
		rm_identity.setRequestHeader('Authorization', 'Bearer ' + access_token);

		if (filter) {
			rm_identity.setQueryParameter('filters', filter);
		}

		const res_identity = rm_identity.execute();

		return res_identity.getBody();
	},

	clientFormConfig: function () {
		const cat_item_id = this.getParameter('sysparm_cat_item');

		const gr_config = new GlideRecord('x_xal_idconnect_catalog_item_config');
		gr_config.get('catalog_item', cat_item_id);

		return JSON.stringify({
			"business_applications": gr_config.getValue('business_applications'),
			"access_item_picker": gr_config.getValue('access_item_picker')
		});
	},
	setRequestedFor: function () {
		const requestedFor = this.getParameter('sysparm_requested_for');
		const itemId = this.getParameter('sysparm_item_id');
		gs.info(`XalientGlideAjaxHelper().setRequestedFor() - value for requestedFor is ${requestedFor} - value for itemId is ${itemId}`);
		if (!requestedFor || !itemId) return;


		var ritm = new GlideRecord('sc_req_item');
		if (ritm.get(itemId)) {
			ritm.requested_for = requestedFor;
			ritm.update();

			var req = new GlideRecord('sc_request');
			if (req.get(ritm.request)) {
				req.requested_for = requestedFor;
				req.update();
			}
		}


	},

	type: 'XalientGlideAjaxHelper'
});
